import{_ as n,a0 as r,w as o,s as p,I as s,x as t,a1 as l,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse(`{"title":"GNOME的文件管理器將對用户更加友好 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME的文件管理器將對用户更加友好 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME的文件管理器將對用户更加友好 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME的文件管理器將對用户更加友好 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/GNOME's File Manager Will Be More User Friendly","title":"GNOME的文件管理器將對用户更加友好","tag":"201312","desc":""},"relativePath":"201312/GNOME's File Manager Will Be More User Friendly.md","filePath":"[post].md"}`),m={name:"201312/GNOME's File Manager Will Be More User Friendly.md"};function d(M,e,N,g,f,E){const i=r("Link");return o(),p("div",null,[e[14]||(e[14]=s("h1",{id:"gnome的文件管理器將對用户更加友好",tabindex:"-1"},[t("GNOME的文件管理器將對用户更加友好 "),s("a",{class:"header-anchor",href:"#gnome的文件管理器將對用户更加友好","aria-label":"Permalink to “GNOME的文件管理器將對用户更加友好”"},"​")],-1)),s("p",null,[s("strong",null,[e[1]||(e[1]=t("幾天前，GNOME的設計師Allan Day在Blog裏發佈了一篇超長博文，介紹了",-1)),l(i,{href:"http://afaikblog.wordpress.com/2013/12/11/nautilus-next/"},{default:a(()=>[...e[0]||(e[0]=[t("GNOME桌面環境下的下一代Nautilus文件管理器",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))])]),e[15]||(e[15]=u('<p>本文將為讀者簡短介紹即將發佈的Nautilus都實現了哪些新的設計功能，這些新功能也將成為GNOME3.12桌面環境的組成部分。</p><p>很顯然，GNOME開發小組對大家一直關注的桌面環境的默認文件管理器進行了美化改進，另外將一些後台功能改放到了顯著位置，使其對新用户更加明顯。</p><p>不管你是否相信，事實是，有非常多的新用户嘗試探索Linux世界之奧秘的時候，面對Nautilus卻一籌莫展，他們不知道如何複製、粘貼、重命名、移動，甚至不知道如何訪問他們的文件…… 這是一個非常窘迫、亟待解決的大問題！</p><p>因此，Nautilus文件管理器的未來版本將着重解決這些問題，包括圖標響應、列表視圖、更大更清晰的縮略圖，以及更好用的縮放層級等等，通過這些，你可以更容易地組織你的文件。同時，更新後的視圖菜單也實現了更優秀的控制操作。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-2.png" alt="Nautilus list view"><em>Nautilus列表視圖</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-3.png" alt="Nautilus grid view"><em>Nautilus圖標視圖</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-4.png" alt="Nautilus gear menu"><em>Nautilus齒輪菜單</em></p><p>Nautilus將要實現的另一個重要特性是各種各樣好用的按鈕。例如“複製到…、移動到…、創建新文件夾、以…打開”等等，它們將使文件操作變得更加友好。同時，文件預覽將變得更加直接，包括一個備受期待的導航功能，它能使照片或文檔瀏覽變得更加容易。</p><p>不僅如此，側邊欄的可定製化程度也會更高，它將允許用户添加或刪除網絡設備、網絡分區，或着是與它們的遠程連接，使整個側邊欄變得更加整潔（這一改進對於像本譯者這樣的強迫症患者來説多麼福音啊~）。新增加的“收藏”標籤可用於訪問所有你最喜歡的文件，還有改進後的“內容選擇功能”，允許用户從多個來源選擇項目。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-5.png" alt="Nautilus add drive dialog"><em>Nautilus添加設備對話框</em></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360-6.png" alt="Nautilus content selection"><em>Nautilus內容選擇</em></p><p>很不幸，目前還沒有渠道供我們編譯測試最新的Nautilus，但開發版發佈的時候，我們會第一時間通知大家。最後提醒大家，Nautilus同時還是Ubuntu Linux的默認文件管理器哦~</p><hr>',13)),s("p",null,[e[4]||(e[4]=t("via: ",-1)),l(i,{href:"http://news.softpedia.com/news/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360.shtml"},{default:a(()=>[...e[3]||(e[3]=[t("http://news.softpedia.com/news/GNOME-s-File-Manager-Will-Be-More-User-Friendly-409360.shtml",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=t("譯者：",-1)),l(i,{href:"http://blog.csdn.net/tinyeyeser"},{default:a(()=>[...e[5]||(e[5]=[t("Mr小眼兒",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),l(i,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[6]||(e[6]=[t("Caroline",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),l(i,{href:"http://linux.cn/"},{default:a(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const G=n(m,[["render",d]]);export{F as __pageData,G as default};
